sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float width;
uniform float edgeCut;
uniform float intensity;
uniform float spread;
uniform float colorMode;
layout(color) uniform half4 edgeColor;
uniform float keepOriginal;
uniform float blend;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float edgeAt(float2 p, float w) {
    float tl = luma(tex(p + float2(-w, -w)).rgb);
    float tc = luma(tex(p + float2(0.0, -w)).rgb);
    float tr = luma(tex(p + float2(w, -w)).rgb);
    float ml = luma(tex(p + float2(-w, 0.0)).rgb);
    float mr = luma(tex(p + float2(w, 0.0)).rgb);
    float bl = luma(tex(p + float2(-w, w)).rgb);
    float bc = luma(tex(p + float2(0.0, w)).rgb);
    float br = luma(tex(p + float2(w, w)).rgb);
    float gx = -tl - 2.0 * ml - bl + tr + 2.0 * mr + br;
    float gy = -tl - 2.0 * tc - tr + bl + 2.0 * bc + br;
    return length(float2(gx, gy));
}
float3 blendm(float3 b, float3 s, float m) {
    if (m < 0.5) return s;
    if (m < 1.5) return b + s;
    if (m < 2.5) return 1.0 - (1.0 - b) * (1.0 - s);
    if (m < 3.5) return b * s;
    if (m < 4.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(float3(0.5), b));
    if (m < 5.5) return (1.0 - 2.0 * s) * b * b + 2.0 * s * b;
    if (m < 6.5) return max(b, s);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return abs(b - s);
    return b / max(1.0 - s, 0.001);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float e0 = edgeAt(coord, width);
    float e1 = edgeAt(coord, width * (1.0 + spread));
    float e2 = edgeAt(coord, width * (1.0 + spread * 3.0));
    float e = saturate((e0 + e1 * 0.6 + e2 * 0.35 - edgeCut) * intensity);
    float3 gc = colorMode < 0.5 ? float3(edgeColor.rgb) : s;
    float3 base = s * keepOriginal;
    float3 o = mix(base, blendm(base, gc, blend), e);
    return fin(c, float4(max(o, float3(0.0)) * c.a, c.a), opacity);
}
